engine.labEngine:
function labEngine() {

  // The drop box format the lab opens (lab/server.js open): "ELIL1" · wrapped-key length (2 bytes) · the
  // AES-GCM key wrapped by the lab's RSA-OAEP public key · IV (12) · ciphertext of [header length (4) ·
  // header JSON · file bytes]. Bytes, not base64 inside JSON, so a contract uploads at ~1.35x its size.
  function labSeal(env, fileBytes, publicKeyB64, subtle, random) {
    var iv = random(new Uint8Array(12));
    var head = new TextEncoder().encode(JSON.stringify(env)), body = fileBytes || new Uint8Array(0);
    var plain = new Uint8Array(4 + head.length + body.length);
    new DataView(plain.buffer).setUint32(0, head.length);
    plain.set(head, 4); plain.set(body, 4 + head.length);
    var spki = Uint8Array.from(atob(publicKeyB64), function (c) { return c.charCodeAt(0); });
    return Promise.all([
      subtle.importKey("spki", spki, { name: "RSA-OAEP", hash: "SHA-256" }, false, ["encrypt"]),
      subtle.generateKey({ name: "AES-GCM", length: 256 }, true, ["encrypt"]),
    ]).then(function (k) {
      return Promise.all([subtle.encrypt({ name: "AES-GCM", iv: iv }, k[1], plain), subtle.exportKey("raw", k[1])]).then(function (r) {
        return subtle.encrypt({ name: "RSA-OAEP" }, k[0], r[1]).then(function (wrapped) {
          var wk = new Uint8Array(wrapped), ct = new Uint8Array(r[0]), out = new Uint8Array(7 + wk.length + 12 + ct.length);
          out.set([69, 76, 73, 76, 49]);   // "ELIL1"
          new DataView(out.buffer).setUint16(5, wk.length);
          out.set(wk, 7); out.set(iv, 7 + wk.length); out.set(ct, 19 + wk.length);
          return out;
        });
      });
    });
  }

  // ── The flight recorder ── The last run only, in memory. A run starts at a tool's first AI call or first
  // Word work that may change the document; opening tools, Home, settings or help don't count, nor does
  // this tool. It keeps each AI request with its answer (for replay), Word work by label and time, and errors.

  function labRecorderNew() { return { run: null, previous: null }; }
  function labRecorderNote(rec, kind, evt, now, ignoreTool) {
    if (!evt || (ignoreTool && evt.tool === ignoreTool)) return rec;
    var starts = (kind === "ai" && evt.type === "request") || (kind === "host" && evt.type === "will");
    if (!rec.run && !starts) return rec;
    // A new tool's first call starts a new run (the old one kept as previous for a moment).
    if (starts && rec.run && evt.tool && rec.run.tool && evt.tool !== rec.run.tool) { rec.previous = rec.run; rec.run = null; }
    if (!rec.run) rec.run = { tool: evt.tool || "", startedAt: now, ai: {}, aiOrder: [], host: [], errors: [], events: 0, dropped: 0, beforeCopy: null, firstWrite: null };
    var r = rec.run;
    if (++r.events > 400) { r.dropped++; return rec; }   // bounded: 400 events a run
    if (kind === "ai") {
      var c = r.ai[evt.id] || (r.ai[evt.id] = { id: evt.id });
      if (evt.type === "request") { c.model = evt.model; c.mode = evt.mode; c.promptChars = evt.promptChars; c.at = now; if (evt.prompt != null) c.prompt = evt.prompt; if (evt.opts) c.opts = evt.opts; r.aiOrder.push(evt.id); }
      else { c.ok = evt.ok; c.ms = evt.ms; c.chars = evt.chars; c.firstMs = evt.firstMs; if (evt.text != null) c.text = evt.text; if (!evt.ok) r.errors.push({ at: now, where: "ai", error: evt.error || "", cancelled: !!evt.cancelled }); }
    } else if (kind === "host") {
      if (evt.type === "will" && !r.firstWrite) r.firstWrite = { at: now, label: evt.label };
      if (evt.type === "done") { r.host.push({ label: evt.label, ok: evt.ok, ms: evt.ms, at: now }); if (!evt.ok) r.errors.push({ at: now, where: "word:" + evt.label, error: "failed" }); }
    }
    return rec;
  }
  // Shape only: what a summary report may carry (no prompt, no answer, no document).
  function labRecorderSummary(run) {
    if (!run) return null;
    var calls = run.aiOrder.map(function (id) { var c = run.ai[id] || {}; return { model: c.model, mode: c.mode, promptChars: c.promptChars, chars: c.chars, ms: c.ms, ok: c.ok }; });
    var words = {};
    run.host.forEach(function (h) { var w = words[h.label] || (words[h.label] = { n: 0, ms: 0, failed: 0 }); w.n++; w.ms += h.ms || 0; if (!h.ok) w.failed++; });
    return { tool: run.tool, startedAt: run.startedAt, aiCalls: calls, word: words, errors: run.errors.map(function (e) { return { where: e.where, cancelled: !!e.cancelled }; }), events: run.events, dropped: run.dropped,
      beforeCopy: run.beforeCopy ? { size: run.beforeCopy.size, sha256: run.beforeCopy.sha256 } : null };
  }
  // Full: prompts and answers as the lab replays them, in order.
  function labRecorderFull(run) {
    if (!run) return null;
    var s = labRecorderSummary(run);
    s.calls = run.aiOrder.map(function (id) { var c = run.ai[id] || {}; return { model: c.model, mode: c.mode, opts: c.opts || null, prompt: c.prompt == null ? null : c.prompt, text: c.text == null ? null : c.text, ok: c.ok, ms: c.ms }; });
    s.errors = run.errors.slice();
    return s;
  }

  // A report's payload. mode "full" (paired, admin): the note, the words selected, the card, the screen, the run's
  // prompts and answers. "summary" (a colleague, later): no document text, no answers, no copy — shapes only.
  function labReportPayload(o, mode) {
    var full = mode === "full";
    var p = { type: o.type === "improvement" ? "improvement" : "bug", note: String(o.note || "").slice(0, 8000), mode: full ? "full" : "summary",
      tool: o.tool || "", screen: o.screen ? { name: o.screen.name || "", status: o.screen.status || "", buttons: (o.screen.buttons || []).slice(0, 60) } : null,
      versions: o.versions || null, settings: o.settings || null, at: o.at || "" };
    if (full) {
      p.selection = o.selection ? String(o.selection).slice(0, 20000) : "";
      p.card = o.card || null;
      p.run = labRecorderFull(o.run);
      p.screenText = o.screenText ? String(o.screenText).slice(0, 80000) : "";
      p.picture = o.picture || null;
    } else {
      p.selection = o.selection ? { chars: String(o.selection).length } : null;
      p.run = labRecorderSummary(o.run);
    }
    return p;
  }

  return { labSeal: labSeal, labRecorderNew: labRecorderNew, labRecorderNote: labRecorderNote, labRecorderSummary: labRecorderSummary,
    labRecorderFull: labRecorderFull, labReportPayload: labReportPayload };
}

view.labView:
function labView() {

  function labEsc(s) { return String(s == null ? "" : s).replace(/[&<>"]/g, function (c) { return { "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;" }[c]; }); }

  // Where an item stands, in words: its work step if Claude Code has it (and who), else its backlog status.
  function labStepWords() { return { queued: "Queued for Claude", "in progress": "In progress", "fix ready": "Fix ready — approve?", approved: "Approved — releasing", released: "Released", "needs you": "Needs you", held: "Held" }; }
  function labStatusWords() { return { open: "Open", approved: "Approved", "partly-fixed": "Partly fixed", "waiting-on-you": "Waiting on you", "on-hold": "On hold", fixed: "Done", wontfix: "Won't fix" }; }
  function labItemState(it) {
    if (it.work && it.work.step !== "released") {
      var w = labStepWords()[it.work.step] || it.work.step;
      if (it.work.step === "in progress") w += " (" + (it.work.by || "Claude Code") + ")";
      return { words: w, you: /fix ready|needs you/.test(it.work.step), done: false };
    }
    var done = it.status === "fixed" || it.status === "wontfix" || (it.work && it.work.step === "released");
    return { words: it.work && it.work.step === "released" ? "Released" : (labStatusWords()[it.status] || it.status), you: it.status === "waiting-on-you", done: done };
  }
  // The summary strip: what needs you first, then what's moving, then the rest.
  function labFilters() { return [["you", "Waiting on me"], ["ready", "Fix ready"], ["progress", "In progress"], ["open", "Open"], ["done", "Done"]]; }
  function labFilterItems(items, f) {
    return (items || []).filter(function (it) {
      var s = labItemState(it);
      if (f === "done") return s.done;
      if (f === "you") return s.you;
      if (f === "ready") return !!(it.work && it.work.step === "fix ready");
      if (f === "progress") return !!(it.work && /^(queued|in progress|approved)$/.test(it.work.step));
      return !s.done && it.status !== "on-hold";
    });
  }
  // Search and the status / tool / type selects, after the strip's filter.
  function labFindItems(items, st) {
    var q = String(st.q || "").trim().toLowerCase();
    return (items || []).filter(function (it) {
      if (st.fStatus && it.status !== st.fStatus) return false;
      if (st.fTool && it.tool !== st.fTool) return false;
      if (st.fType && it.type !== st.fType) return false;
      return !q || (it.id + " " + it.title + " " + (it.feature || "") + " " + (it.tool || "")).toLowerCase().indexOf(q) >= 0;
    });
  }
  // Where an item is on its way: reported → reproduced → fix ready → approved → released → verified.
  function labStages() { return ["Reported", "Reproduced", "Fix ready", "Approved", "Released", "Verified"]; }
  function labStage(it) {
    var seen = (it.timeline || []).map(function (e) { return String(e.what || "").toLowerCase(); }).join("|"), step = it.work && it.work.step;
    if (it.verified || /verified/.test(seen)) return 5;
    if (it.status === "fixed" || step === "released" || /released/.test(seen)) return 4;
    if (it.status === "approved" || step === "approved" || /approved/.test(seen)) return 3;
    if (step === "fix ready" || /fix ready/.test(seen)) return 2;
    if (/reproduced|fixed in the lab/.test(seen)) return 1;
    return 0;
  }
  function labRenderStepper(it) {
    var at = labStage(it);
    return '<ol class="_el_stepper" aria-label="Where it stands">' + labStages().map(function (s, i) {
      return '<li class="' + (i < at ? "_el_done" : i === at ? "_el_now" : "") + '"' + (i === at ? ' aria-current="step"' : "") + "><span>" + s + "</span></li>";
    }).join("") + "</ol>";
  }
  // New: a report not yet opened here. Pinned at the top, newest first; the rest newest first (an item that carries
  // only the day it was added counts from that day's start) or by priority.
  function labIsNew(it, seen) { return !!(it.report && !(seen || {})[it.id] && !labItemState(it).done); }
  function labSortItems(items, sort, seen) {
    var t = function (it) { var a = String(it.at || ""); return Date.parse(a.length > 10 ? a : a + "T00:00:00") || 0; };
    return (items || []).slice().sort(function (a, b) {
      return (labIsNew(b, seen) ? 1 : 0) - (labIsNew(a, seen) ? 1 : 0) ||
        (sort === "priority" ? (a.priority || 9) - (b.priority || 9) : sort === "tool" ? String(a.tool || "~").localeCompare(String(b.tool || "~")) : 0) || t(b) - t(a) || String(a.id).localeCompare(String(b.id), "en", { numeric: true });
    });
  }
  function labWhen(iso) {
    if (!iso) return "";
    var s = String(iso);
    if (s.length <= 10) { var day = new Date(s + "T00:00:00"); return isNaN(day) ? "" : day.toLocaleDateString([], { month: "short", day: "numeric" }); }
    var d = new Date(s);
    if (isNaN(d)) return "";
    var mins = Math.round((Date.now() - d.getTime()) / 60000);
    if (mins < 1) return "just now";
    if (mins < 60) return mins + " min ago";
    if (mins < 1440) return Math.round(mins / 60) + " h ago";
    return d.toLocaleDateString([], { month: "short", day: "numeric" });
  }
  function labClock(iso) { var d = new Date(iso); return isNaN(d) ? "" : d.toLocaleString([], { month: "short", day: "numeric", hour: "numeric", minute: "2-digit" }); }

  // st: { tab, filter, sort, seen, items, asOf, live, open (item id), addressing (item id), sending, error, paired, recorder,
  //       pics, zoom, q, fStatus, fTool, fType, work (read-only, from the snapshot), noKey }
  // The list reads as a brief (a headline, then items grouped under where they stand); an item opens as its own page.
  function labRenderPanel(st) {
    var work = !!st.work;
    var items = labSortItems(labFindItems(labFilterItems(st.items, st.filter || "open"), st), st.sort, st.seen), counts = {};
    labFilters().forEach(function (f) { counts[f[0]] = labFilterItems(st.items, f[0]).length; });
    var opened = st.open ? (st.items || []).filter(function (x) { return x.id === st.open; })[0] : null;
    return '<div class="_el_root' + (work ? " _el_work" : "") + '">' +
      '<div class="_el_bar"><button type="button" class="_el_back" data-el="' + (opened ? "close" : "home") + '" aria-label="' + (opened ? "Back to the list" : "Back to Home") + '">‹</button>' +
        '<div class="_el_bar_title">ELI Lab</div>' +
        '<span class="_el_pill _el_pill_bar">' + (work ? "Read-only" + (st.asOf ? " · " + labEsc(labWhen(st.asOf)) : "") : st.live ? "Connected" : st.asOf ? "As of " + labEsc(labWhen(st.asOf)) : "Not connected") + '</span>' +
        '<button type="button" class="_el_refresh" data-el="refresh" aria-label="Refresh the list" title="Refresh">↻</button></div>' +
      (opened ? labRenderItemPage(opened, st) :
      '<div class="_el_tabs" role="tablist">' +
        '<button type="button" role="tab" class="_el_tab' + (st.tab !== "lab" ? " _el_on" : "") + '" data-el="tab:items" aria-selected="' + (st.tab !== "lab") + '">Bugs &amp; requests</button>' +
        (work ? "" : '<button type="button" role="tab" class="_el_tab' + (st.tab === "lab" ? " _el_on" : "") + '" data-el="tab:lab" aria-selected="' + (st.tab === "lab") + '">Lab</button>') +
        '<button type="button" class="_el_tab_action btn-platinum" data-el="report"' + (work ? ' disabled title="Available at home"' : "") + ">Report…</button></div>" +
      (st.tab === "lab" ? labRenderLabTab(st) :
        labRenderStrip(st, counts) +
        labRenderFind(st) +
        (st.error ? '<div class="_el_note_err">' + labEsc(st.error) + "</div>" : "") +
        (items.length ? labRenderGroups(items, st) :
          work && st.noKey && !(st.items && st.items.length) ? '<div class="_el_empty"><div class="_el_empty_title">Locked</div><div class="_el_empty_msg">Import your admin key (credentials file) to view.</div></div>' :
          '<div class="_el_empty"><div class="_el_empty_title">' + ({ open: "Nothing open", you: "Nothing waiting on you", ready: "No fixes waiting", progress: "Nothing in progress", done: "Nothing done yet" }[st.filter || "open"]) +
          '</div><div class="_el_empty_msg">' + (st.items && st.items.length ? "Try another filter or clear the search." : work ? "The list arrives with ELI's next update check." : st.live ? "The lab's list is empty." : "Connect to the lab to see its list.") + "</div></div>"))) +
      (st.zoom ? '<div class="_el_zoom" data-el="zoomClose" role="dialog" aria-label="Picture"><img src="' + labEsc(st.zoom) + '" alt=""><button type="button" class="_el_x" data-el="zoomClose" aria-label="Close">×</button></div>' : "") +
    "</div>";
  }
  // The headline (what needs you, in one sentence), then the chips, which are also the filter.
  function labRenderStrip(st, counts) {
    var f0 = st.filter || "open";
    var ask = counts.you - labFilterItems(st.items, "you").filter(function (it) { return it.work && it.work.step === "fix ready"; }).length;   // fix-ready items wait on you too
    var said = [counts.ready ? counts.ready + " fix" + (counts.ready === 1 ? "" : "es") + " to approve" : "", ask > 0 ? ask + " question" + (ask === 1 ? "" : "s") + " for you" : "", counts.progress ? counts.progress + " in progress" : ""].filter(Boolean);
    return '<p class="_el_brief">' + (said.length ? said.join(" · ") : "Nothing needs you") + "<span>" + counts.open + " open · " + counts.done + " done</span></p>" +
      '<div class="_el_filters" role="group" aria-label="Show">' + labFilters().map(function (f) {
        return '<button type="button" class="_el_chip' + (f0 === f[0] ? " _el_on" : "") + '" data-el="filter:' + f[0] + '" aria-pressed="' + (f0 === f[0]) + '">' + f[1] + ' <span class="_el_chip_n">' + counts[f[0]] + "</span></button>";
      }).join("") + "</div>";
  }
  // Search, the order, and the status / tool / type selects.
  function labRenderFind(st) {
    var all = st.items || [], opts = function (key, names) {
      return all.map(function (x) { return x[key]; }).filter(function (v, i, a) { return v && a.indexOf(v) === i; }).sort()
        .map(function (v) { return '<option value="' + labEsc(v) + '"' + (st["f" + key.charAt(0).toUpperCase() + key.slice(1)] === v ? " selected" : "") + ">" + labEsc((names && names[v]) || v) + "</option>"; }).join("");
    };
    return '<div class="_el_find">' +
      '<input id="_el_q" class="_el_search" type="search" placeholder="Search" aria-label="Search titles and ids" data-el-input="q" value="' + labEsc(st.q || "") + '">' +
      '<span class="_el_sort" role="radiogroup" aria-label="Order">' + [["newest", "Newest"], ["priority", "Priority"], ["tool", "Tool"]].map(function (o) {
        return '<button type="button" role="radio" aria-checked="' + ((st.sort || "newest") === o[0]) + '" class="_el_sort_opt' + ((st.sort || "newest") === o[0] ? " _el_on" : "") + '" data-el="sort:' + o[0] + '">' + o[1] + "</button>";
      }).join("") + "</span>" +
      '<select id="_el_f_status" class="_el_select" aria-label="Status" data-el-select="fStatus"><option value="">Any status</option>' + opts("status", labStatusWords()) + "</select>" +
      '<select id="_el_f_tool" class="_el_select" aria-label="Tool" data-el-select="fTool"><option value="">Any tool</option>' + opts("tool") + "</select>" +
      '<select id="_el_f_type" class="_el_select" aria-label="Type" data-el-select="fType"><option value="">Any type</option>' + opts("type") + "</select></div>";
  }
  // The list, grouped under where each item stands (each item once, in the first group it fits).
  function labRenderGroups(items, st) {
    var groups = [["ready", "Fixes to approve"], ["you", "Questions for you"], ["progress", "In progress"], ["rest", "Everything else open"], ["done", "Done"]], used = {};
    return groups.map(function (g) {
      var mine = items.filter(function (it) {
        if (used[it.id]) return false;
        var hit = g[0] === "rest" ? !labItemState(it).done : g[0] === "done" ? labItemState(it).done : labFilterItems([it], g[0]).length > 0;
        if (hit) used[it.id] = true;
        return hit;
      });
      return mine.length ? '<section class="_el_group"><h3 class="_el_group_h">' + g[1] + " <span>" + mine.length + '</span></h3><ul class="_el_list">' + mine.map(function (it) { return labRenderItem(it, st); }).join("") + "</ul></section>" : "";
    }).join("");
  }
  // A row: title and where it stands; it opens the item's page.
  function labRenderItem(it, st) {
    var s = labItemState(it), isNew = labIsNew(it, st.seen);
    return '<li class="_el_item' + (isNew ? " _el_item_new" : "") + '">' +
      '<button type="button" class="_el_item_head" data-el="open:' + labEsc(it.id) + '">' +
        '<span class="_el_item_title">' + (isNew ? '<span class="_el_new">New</span>' : "") + labEsc(it.title) + '<span class="_el_chev" aria-hidden="true">›</span></span>' +
        '<span class="_el_item_meta"><span class="_el_pri' + (it.priority === 1 ? " _el_pri1" : "") + '">P' + labEsc(it.priority || "–") + "</span>" +
          '<span class="_el_kind_word">' + labEsc(it.feature || it.type || "") + "</span>" +
          '<span class="_el_pill' + (s.you ? " _el_pill_you" : s.done ? " _el_pill_done" : "") + '">' + labEsc(s.words) + "</span>" +
          (it.at ? '<span class="_el_when" title="' + labEsc(it.timed ? labClock(it.at) : it.at) + '">' + labEsc(labWhen(it.at)) + "</span>" : "") + "</span>" +
      "</button></li>";
  }
  // An item's own page: its id and feature, a serif title, where it stands, then its record. ‹ goes back to the list.
  function labRenderItemPage(it, st) {
    var s = labItemState(it);
    return '<article class="_el_detail">' +
      '<header class="_el_detail_head"><span class="_el_detail_id">' + labEsc(it.id) + (it.feature || it.tool ? " · " + labEsc(it.feature || it.tool) : "") + "</span>" +
        '<h2 class="_el_detail_title">' + labEsc(it.title) + "</h2>" +
        '<span class="_el_item_meta"><span class="_el_pri' + (it.priority === 1 ? " _el_pri1" : "") + '">P' + labEsc(it.priority || "–") + '</span><span class="_el_pill' + (s.you ? " _el_pill_you" : s.done ? " _el_pill_done" : "") + '">' + labEsc(s.words) + "</span>" +
        (it.at ? '<span class="_el_when">' + labEsc(labWhen(it.at)) + "</span>" : "") + "</span></header>" +
      labRenderBody(it, st) + "</article>";
  }
  // An item's record: the stepper, re-test, pictures, decision, diagnosis, fix, history, work log, then what you can do.
  // At work (read-only snapshot): no document wording, no pictures, the actions greyed.
  function labRenderBody(it, st) {
    var s = labItemState(it), work = !!st.work, addr = st.addressing === it.id && !work, home = ' disabled title="Available at home"';
    var conf = '<div class="_el_conf">Confidential — visible at home</div>';
    return labRenderStepper(it) +
        (it.description ? '<p class="_el_desc">' + labEsc(it.description) + "</p>" : "") +
        '<div class="_el_kv"><span>Item</span><b>' + labEsc(it.id) + "</b>" + (it.tool ? " · " + labEsc(it.feature ? it.feature + " (" + it.tool + ")" : it.tool) : "") + "</div>" +
        (!work && it.cases && it.cases.length ? '<div class="_el_kv"><span>Test case' + (it.cases.length > 1 ? "s" : "") + "</span>" + it.cases.map(labEsc).join(", ") + "</div>" : "") +
        (work ? labRenderRuns(it) : labRenderRetest(it, st)) +
        labRenderPictures(it, st) +
        (it.decision ? '<div class="_el_block"><div class="_el_block_h">Decision</div>' + (it.decision.confidential ? conf : '<div class="_el_quote">' + labEsc(it.decision.text) + '<div class="_el_by">' + labEsc(it.decision.by || "") + (it.decision.at ? " · " + labEsc(labClock(it.decision.at)) : "") + "</div></div>") + "</div>" : "") +
        (it.diagnosis && it.diagnosis.length ? '<div class="_el_block"><div class="_el_block_h">Diagnosis</div><ul class="_el_bullets">' + it.diagnosis.map(function (d) { return "<li>" + labEsc(d) + "</li>"; }).join("") + "</ul></div>" : "") +
        (it.fixes && it.fixes.length ? '<div class="_el_block"><div class="_el_block_h">The fix</div><ul class="_el_bullets">' + it.fixes.map(function (f) {
          if (typeof f === "string") return "<li>" + labEsc(f) + "</li>";   // the read-only snapshot's safe words
          return "<li><b>" + labEsc(f.where) + "</b> — " + labEsc(f.what) + (f.state ? ' <span class="_el_state">' + labEsc(f.state) + "</span>" : "") + (f.tests ? '<div class="_el_by">Tests: ' + labEsc(f.tests) + "</div>" : "") + "</li>";
        }).join("") + "</ul></div>" : "") +
