            '<div class="_el_row_end"><button type="button" class="btn-platinum" data-el="addrCancel">Cancel</button><button type="button" class="_el_primary" data-el="addrSend:' + labEsc(it.id) + '"' + (st.sending ? " disabled" : "") + ">" + (st.sending ? "Sending…" : "Send to Claude Code") + "</button></div></div>"
