      (fresh ? '<div class="_el_fresh">The fixed code asks the AI something the recording doesn’t have: needs ' + r.missing + " fresh AI answer" + (r.missing === 1 ? "" : "s") + '. <button type="button" class="btn-platinum" data-el="retestFresh:' + labEsc(it.id) + ":" + r.missing + '">Run it</button></div>' : "") +
