jsonTools.init:
function init(eli) {
  var bundle = eli.tools._loaded["eli_lab"] || {}, ef = bundle._eliEngineFns || {}, vf = bundle._eliViewFns || {};
  var E = typeof ef.labEngine === "function" ? ef.labEngine() : {}, V = typeof vf.labView === "function" ? vf.labView() : {};
  if (!eli.lab || !E.labRecorderNote || !V.labRenderReport) { eli.log.event("tool", "eli_lab_init_missing", { lab: !!eli.lab }); return; }
  var SELF = "eli_lab", rec = E.labRecorderNew(), paired = false, offs = [], beforeCopy = null, box = null;
  // A newer copy of this tool (an update, a hot reload) replaces the old one: its button and its observers go.
  if (window.__eliLabTool && typeof window.__eliLabTool.stop === "function") { try { window.__eliLabTool.stop(); } catch (_) {} }
