    };
  }
  function startRecorder() {
    return eli.lab.status().then(function (s) {
      paired = !!s.paired; box = s;
      if (!paired) return;
      return Promise.all([eli.lab.observe("ai", note("ai")), eli.lab.observe("host", note("host"))]).then(function (u) { offs = offs.concat(u); });
    }).catch(function (e) { eli.log.event("tool", "eli_lab_recorder_off", { msg: e && e.message }); });
  }

  // ── The picture ── the pane drawn through SVG (styles inlined); null if the browser won't.
  function panePicture() {
    try {
      var css = [];
      [].forEach.call(document.styleSheets, function (s) { try { [].forEach.call(s.cssRules || [], function (r) { css.push(r.cssText); }); } catch (_) {} });
      var w = Math.max(document.documentElement.clientWidth, 320), h = Math.max(document.documentElement.clientHeight, 200);
      var svg = '<svg xmlns="http://www.w3.org/2000/svg" width="' + w + '" height="' + h + '"><foreignObject width="100%" height="100%"><div xmlns="http://www.w3.org/1999/xhtml"><style>' +
        css.join("\n").replace(/<\/style/gi, "<\\/style") + "</style>" + new XMLSerializer().serializeToString(document.body) + "</div></foreignObject></svg>";
      return new Promise(function (resolve) {
        var img = new Image();
        img.onload = function () { try { var c = document.createElement("canvas"); c.width = w; c.height = h; var g = c.getContext("2d"); g.fillStyle = "#fff"; g.fillRect(0, 0, w, h); g.drawImage(img, 0, 0); resolve(c.toDataURL("image/png")); } catch (_) { resolve(null); } };
        img.onerror = function () { resolve(null); };
        img.src = "data:image/svg+xml;charset=utf-8," + encodeURIComponent(svg);
      });
    } catch (_) { return Promise.resolve(null); }
  }
  // What's on screen, without its text: the tool, its status, the buttons.
  function screenState() {
    var a = eli.perf && eli.perf.activeTool ? eli.perf.activeTool() : "";
    var buttons = [].slice.call(document.querySelectorAll("button")).filter(function (b) { return b.offsetParent && b.id !== "_el_report"; }).map(function (b) { return (b.innerText || "").trim().slice(0, 40); }).filter(Boolean);
    return { name: a || "", status: (eli.fsm && eli.fsm.current && eli.fsm.current()) || "", buttons: buttons };
  }

  // ── The form ──
  var st = null, host = null;
  function paint() { if (host) host.innerHTML = V.labRenderReport(st); }
  function close() { if (host && host.parentNode) host.parentNode.removeChild(host); host = null; st = null; }
  function open() {
