    var shot = panePicture(), sel = eli.host.getSelection ? eli.host.getSelection().catch(function () { return null; }) : Promise.resolve(null);
    Promise.all([shot, sel, eli.lab.hello().catch(function () { return { ok: false }; })]).then(function (r) {
      var run = rec.run || rec.previous;
      st = { type: "bug", note: "", picture: r[0], selection: r[1] && r[1].text ? String(r[1].text) : "", paired: paired,
        reach: r[2] && r[2].ok ? "lab" : paired && box && box.mailbox ? "box" : "none", screen: screenState(),
        run: run ? { tool: run.tool, aiCalls: run.aiOrder.length, errors: run.errors.length } : null };
      host = document.createElement("div"); host.className = "_el_overlay"; document.body.appendChild(host);
