      versions: { kernel: eli.kernelVersion }, screenText: full ? (document.body.innerText || "").slice(0, 80000) : "" }, full ? "full" : "summary");
    var kind = st.type === "improvement" ? "improve.request" : "bug.report", copy = run && run.beforeCopy, opts = copy ? { bytes: copy.bytes, name: copy.name, sha256: copy.sha256 } : undefined;
    var done = function (where) { st.sending = false; st.sent = where; paint(); setTimeout(close, 1500); };
    var fail = function (e) { st.sending = false; st.error = "Not sent: " + (e && e.message || e); paint(); };
    if (!full) {   // a summary: never document text, never to the lab — to the clipboard for the admin
      var text = JSON.stringify(payload, null, 2);
      return (navigator.clipboard ? navigator.clipboard.writeText(text) : Promise.reject(new Error("no clipboard"))).then(function () { done("to the clipboard"); }, fail);
    }
    if (st.reach === "lab") {
      // The big parts (the run's prompts and answers, the picture, the screen) go first, in pieces under the kernel's
      // 256 KB request limit; the report names them and the lab joins them (kinds report.part).
      var rid = "r" + Date.now().toString(36) + Math.random().toString(36).slice(2, 6), parts = [], sends = [];
      ["run", "picture", "screenText"].forEach(function (name) {
        if (payload[name] == null) return;
        var text = typeof payload[name] === "string" ? payload[name] : JSON.stringify(payload[name]), PIECE = 100000, part = name.toLowerCase();   // part names are lowercase
        parts.push(part); delete payload[name];
        for (var i = 0, seq = 0; i < text.length; i += PIECE, seq++) sends.push({ report: rid, part: part, seq: seq, data: text.slice(i, i + PIECE) });
      });
