      return sends.reduce(function (pr, part) { return pr.then(function () { return eli.lab.send("report.part", part); }); }, Promise.resolve())
        .then(function () { return eli.lab.send(kind, payload, opts); }).then(function (r) { done("to the lab" + (r && r.receipt && r.receipt.item ? " as " + r.receipt.item : "")); }, fail);
    }
