      var env = { v: 1, id: "m" + Date.now().toString(36) + Math.random().toString(36).slice(2, 8), kind: kind, payload: payload, at: new Date().toISOString(),
        from: { kernel: eli.kernelVersion, tool: SELF }, document: copy ? { name: copy.name, size: copy.size, sha256: copy.sha256 } : undefined };
      return E.labSeal(env, copy ? copy.bytes : null, box.publicKey, window.crypto.subtle, function (a) { return window.crypto.getRandomValues(a); })
        .then(function (sealed) { return eli.lab.box.put("inbox/" + env.id + ".elil", sealed); }).then(function () { done("to the drop box"); }, fail);
    }
    fail(new Error("the lab isn't reachable and there's no drop box"));
  }

  // ── The button ── in ELI's header, just left of the gear, on every screen. The header's own click goes Home,
  // so this one stops there.
  var btn = document.createElement("button");
  btn.id = "_el_report"; btn.type = "button"; btn.title = "Report a problem or an improvement to the ELI Test Lab"; btn.setAttribute("aria-label", "Report to the ELI Test Lab");
  btn.innerHTML = '<svg viewBox="0 0 16 16" aria-hidden="true"><path d="M3.5 1.75v12.5" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" fill="none"/>' +
    '<path d="M4 2.5h7.2l-1.6 2.75 1.6 2.75H4z" fill="currentColor" fill-opacity=".22" stroke="currentColor" stroke-width="1.2" stroke-linejoin="round"/></svg><span>Report</span>';
