  else document.body.appendChild(btn);   // no ELI header on this page: a small fixed button instead

  // ── The panel (dashboard tile): Bugs & requests, read from the lab; the last list kept for when it's away ──
  var STORE_CONFIG = "config", CACHE_KEY = "eli_lab_backlog_cache", PREFS_KEY = "eli_lab_prefs", SEEN_KEY = "eli_lab_seen";
  var ps = { tab: "items", filter: "open", sort: "newest", seen: {}, pics: {}, items: [], asOf: "", live: false }, root = null, ticker = null;
  function paintPanel() {
